options.css:
:host, .dashboard-wrapper {
  --bg: #090c12;
  --surface: #101520;
  --surface-2: #151b28;
  --line: #1d2534;
  --line-2: #2b3550;
  --txt: #f1f5f9;
  --txt-2: #93a3bd;
  --txt-3: #5c6b85;
  --blue: #3b82f6;
  --violet: #8b5cf6;
  --green: #10b981;
  --amber: #f59e0b;
  --rose: #f43f5e;
  --sans: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  --mono: ui-monospace, SFMono-Regular, 'SF Mono', Menlo, Consolas, monospace;
}

.dashboard-wrapper { position: relative; display: flex; flex-direction: column; height: 100%; padding: 8px; gap: 10px; font-family: var(--sans); box-sizing: border-box; overflow: hidden; color: var(--txt); }
.dashboard-wrapper * { box-sizing: border-box; }

/* ============ üst panel ============ */
.controls-bar { display: flex; justify-content: space-between; align-items: center; gap: 16px; flex: 0 0 auto;
  background: linear-gradient(180deg, #141a27 0%, #10151f 100%); border: 1px solid var(--line); padding: 10px 14px; border-radius: 16px; }
.controls-right { display: flex; align-items: center; gap: 8px; flex: 0 0 auto; }

.folder-tabs { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; min-width: 0; }
.folder-btn { position: relative; background: var(--surface-2); border: 1px solid var(--line); color: var(--txt-2); padding: 9px 18px; border-radius: 11px;
  cursor: pointer; font-size: 13px; font-weight: 700; letter-spacing: .3px; white-space: nowrap; font-family: inherit;
  display: inline-flex; align-items: center; gap: 8px; transition: background-color .14s ease, color .14s ease, border-color .14s ease; }
.folder-btn:hover { background: #1d2534; color: var(--txt); border-color: var(--line-2); }
.folder-btn:focus-visible { outline: 2px solid var(--blue); outline-offset: 2px; }
.folder-btn.active { background: linear-gradient(135deg, #2563eb, #1e40af); border-color: #60a5fa; color: #fff; box-shadow: 0 0 0 1px rgba(96,165,250,.25), 0 6px 18px rgba(37,99,235,.35); }
.tab-count { font-family: var(--mono); font-size: 10px; font-weight: 700; line-height: 1; padding: 3px 6px; border-radius: 6px;
  background: rgba(244,63,94,.16); color: #fda4af; border: 1px solid rgba(244,63,94,.35); }
.tab-count.zero { display: none; }

.search-wrap { position: relative; display: flex; align-items: center; }
.search-ico { position: absolute; left: 11px; color: var(--txt-3); font-size: 14px; pointer-events: none; }
.search-input { background: #070a0f; border: 1px solid var(--line); color: var(--txt); padding: 9px 34px 9px 30px; border-radius: 11px; font-size: 13px;
  outline: none; min-width: 210px; font-family: inherit; transition: border-color .14s, box-shadow .14s; }
.search-input:focus { border-color: var(--blue); box-shadow: 0 0 0 3px rgba(59,130,246,.15); }
.search-input:focus + .kbd { opacity: 0; }
.kbd { position: absolute; right: 9px; font-family: var(--mono); font-size: 10px; color: var(--txt-3); border: 1px solid var(--line); border-radius: 5px; padding: 2px 5px; pointer-events: none; transition: opacity .14s; }

.icon-btn { background: var(--surface-2); border: 1px solid var(--line); color: var(--txt-2); width: 36px; height: 36px; border-radius: 11px; cursor: pointer;
  font-size: 15px; line-height: 1; font-family: inherit; transition: background-color .14s, color .14s, border-color .14s; }
.icon-btn:hover { background: #1d2534; color: var(--txt); border-color: var(--line-2); }
.icon-btn:focus-visible { outline: 2px solid var(--blue); outline-offset: 2px; }

/* ============ status zolağı ============ */
.status-strip { display: flex; align-items: center; justify-content: space-between; gap: 18px; flex: 0 0 auto; padding: 0 6px; }
.strip-left { display: flex; align-items: center; gap: 14px; min-width: 0; flex: 1 1 auto; }
.strip-right { display: flex; align-items: center; gap: 14px; flex: 0 0 auto; }

.chips { display: flex; gap: 6px; flex: 0 0 auto; }
.chip { display: inline-flex; align-items: baseline; gap: 6px; background: transparent; border: 1px solid transparent; color: var(--txt-3);
  padding: 5px 10px; border-radius: 9px; cursor: pointer; font-family: inherit; font-size: 11px; font-weight: 600; letter-spacing: .3px;
  transition: background-color .14s, color .14s, border-color .14s; }
.chip .chip-n { font-family: var(--mono); font-size: 14px; font-weight: 700; color: var(--txt-2); }
.chip:hover { background: rgba(255,255,255,.04); color: var(--txt-2); }
.chip.active { background: rgba(255,255,255,.05); border-color: var(--line-2); color: var(--txt); }
.chip.c-red .chip-n { color: #fb7185; }
.chip.c-yellow .chip-n { color: #fbbf24; }
.chip.c-green .chip-n { color: #34d399; }
.chip.c-red.active { border-color: rgba(244,63,94,.45); background: rgba(244,63,94,.10); }
.chip.c-yellow.active { border-color: rgba(245,158,11,.45); background: rgba(245,158,11,.10); }
.chip.c-green.active { border-color: rgba(16,185,129,.45); background: rgba(16,185,129,.10); }
.chip.empty { opacity: .35; }

.health { display: flex; height: 6px; border-radius: 6px; overflow: hidden; background: #0d1119; flex: 1 1 auto; min-width: 80px; max-width: 460px; border: 1px solid var(--line); }
.h-seg { display: block; height: 100%; width: 0; transition: width .5s cubic-bezier(.4,0,.2,1); }
.h-green { background: linear-gradient(90deg, #059669, #10b981); }
.h-yellow { background: linear-gradient(90deg, #d97706, #f59e0b); }
.h-red { background: linear-gradient(90deg, #e11d48, #fb7185); }

.sorts { display: flex; gap: 2px; background: var(--surface); border: 1px solid var(--line); border-radius: 10px; padding: 3px; }
.sort-btn { background: transparent; border: 0; color: var(--txt-3); font-family: inherit; font-size: 11px; font-weight: 700; letter-spacing: .3px;
  padding: 5px 11px; border-radius: 7px; cursor: pointer; transition: background-color .14s, color .14s; }
.sort-btn:hover { color: var(--txt-2); }
.sort-btn.active { background: var(--surface-2); color: var(--txt); box-shadow: inset 0 0 0 1px var(--line-2); }

.live { display: inline-flex; align-items: center; gap: 7px; font-family: var(--mono); font-size: 11px; color: var(--txt-3); white-space: nowrap; }
.live-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--green); box-shadow: 0 0 0 0 rgba(16,185,129,.6); animation: ping 2.4s ease-out infinite; }
@keyframes ping { 0% { box-shadow: 0 0 0 0 rgba(16,185,129,.5); } 70% { box-shadow: 0 0 0 7px rgba(16,185,129,0); } 100% { box-shadow: 0 0 0 0 rgba(16,185,129,0); } }
.live.stale .live-dot { background: var(--amber); animation: none; }

/* ============ grid ============ */
#grid { position: relative; flex: 1 1 auto; min-height: 0; overflow-y: auto; overflow-x: hidden; padding: 2px 4px 2px 2px; }
#grid::-webkit-scrollbar { width: 10px; }
#grid::-webkit-scrollbar-track { background: transparent; }
#grid::-webkit-scrollbar-thumb { background: #232c3f; border-radius: 8px; }
#grid::-webkit-scrollbar-thumb:hover { background: #33405c; }

.folder-page { display: none; grid-template-columns: repeat(auto-fill, minmax(340px, 1fr)); grid-auto-rows: 166px; gap: 14px; align-content: start; }
.folder-page.active { display: grid; animation: pageIn .24s cubic-bezier(.16,1,.3,1); }
@keyframes pageIn { from { opacity: 0; transform: translateY(7px); } to { opacity: 1; transform: none; } }

/* ============ kart ============ */
.cell { --accent: var(--green); --fill: 0%;
  position: relative; background: linear-gradient(180deg, #141a26 0%, #0f141d 100%); border: 1px solid var(--line); border-radius: 14px;
  padding: 15px 18px 16px; display: flex; flex-direction: column; justify-content: space-between; cursor: pointer; user-select: none; overflow: hidden;
  transition: transform .16s cubic-bezier(.16,1,.3,1), border-color .16s, box-shadow .16s;
  content-visibility: auto; contain-intrinsic-size: 166px 340px; }
.cell::before { content: ''; position: absolute; inset: 0 0 auto 0; height: 3px; background: rgba(255,255,255,.05); }
.cell::after { content: ''; position: absolute; top: 0; left: 0; height: 3px; width: var(--fill); background: var(--accent);
  box-shadow: 0 0 12px -1px var(--accent); transition: width .5s cubic-bezier(.4,0,.2,1); }
.cell:hover { transform: translateY(-3px); border-color: var(--line-2); box-shadow: 0 12px 28px rgba(0,0,0,.5); }
.cell:focus-visible { outline: 2px solid var(--blue); outline-offset: 2px; }
.cell.hidden { display: none; }

.cell-header { display: flex; align-items: center; gap: 8px; }
.drag-handle { display: none; touch-action: none; color: var(--violet); font-size: 15px; padding: 1px 3px; border-radius: 4px; cursor: grab; }
.badge { margin-left: auto; font-size: 11px; font-weight: 800; padding: 4px 9px; border-radius: 6px; text-transform: uppercase; letter-spacing: .6px; font-family: var(--mono); }

.name { font-size: 14px; font-weight: 600; color: var(--txt-2); text-transform: uppercase; letter-spacing: .4px; line-height: 1.32;
  margin: 8px 0 0; display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2; line-clamp: 2;
  overflow: hidden; overflow-wrap: anywhere; word-break: break-word; }

.cell-foot { display: flex; align-items: flex-end; justify-content: space-between; gap: 8px; }
.val-wrap { display: flex; align-items: baseline; gap: 7px; min-width: 0; }
.val { font-family: var(--mono); font-size: 35px; font-weight: 700; color: var(--txt); line-height: 1; letter-spacing: -1px; font-variant-numeric: tabular-nums; }
.delta { font-family: var(--mono); font-size: 12px; font-weight: 700; padding: 2px 5px; border-radius: 5px; white-space: nowrap; opacity: 0; transition: opacity .2s; }
.delta.on { opacity: 1; }
.delta.up { color: #fbbf24; background: rgba(245,158,11,.13); }
.delta.down { color: #34d399; background: rgba(16,185,129,.13); }

.spark { flex: 0 0 auto; width: 94px; height: 34px; overflow: visible; }
.spark-area { fill: var(--accent); opacity: .13; }
.spark-line { fill: none; stroke: var(--accent); stroke-width: 1.6; stroke-linejoin: round; stroke-linecap: round; opacity: .85; }

.cell.status-green { --accent: var(--green); }
.cell.status-green .badge { background: rgba(16,185,129,.14); color: #34d399; box-shadow: inset 0 0 0 1px rgba(16,185,129,.3); }
.cell.status-yellow { --accent: var(--amber); }
.cell.status-yellow .badge { background: rgba(245,158,11,.14); color: #fbbf24; box-shadow: inset 0 0 0 1px rgba(245,158,11,.32); }
.cell.status-red { --accent: var(--rose); background: linear-gradient(180deg, rgba(244,63,94,.10) 0%, #0f141d 62%); border-color: rgba(244,63,94,.28); }
.cell.status-red .badge { background: rgba(244,63,94,.16); color: #fb7185; box-shadow: inset 0 0 0 1px rgba(244,63,94,.38); }
.cell.status-red .val { color: #fff; }
.folder-page:not(.no-pulse) .cell.status-red::after { animation: rail 2.6s ease-in-out infinite; }
@keyframes rail { 0%, 100% { opacity: 1; } 50% { opacity: .45; } }

/* ============ düzəliş rejimi ============ */
.mode-btn.active { background: linear-gradient(135deg, #7c3aed, #5b21b6); border-color: #a78bfa; color: #fff; box-shadow: 0 0 0 1px rgba(167,139,250,.3), 0 6px 18px rgba(124,58,237,.35); }
.edit-hint { display: none; font-size: 11px; font-weight: 600; color: #a78bfa; letter-spacing: .3px; white-space: nowrap; }
.dashboard-wrapper.editing .edit-hint { display: inline; }
.dashboard-wrapper.editing .controls-bar { border-color: rgba(167,139,250,.4); }
.dashboard-wrapper.editing .drag-handle { display: inline-block; }
.dashboard-wrapper.editing .drag-handle:active { cursor: grabbing; }
.dashboard-wrapper.editing .folder-page { outline: 1px dashed rgba(167,139,250,.25); outline-offset: 9px; border-radius: 18px; }
.dashboard-wrapper.editing .cell { cursor: default; }
.dashboard-wrapper.editing .cell:hover { transform: none; box-shadow: none; border-color: rgba(167,139,250,.45); }
/* Sürüşdürülən kartın yeri: solğun kart yox, aydın "yuva" */
.cell.drag-source { opacity: 1; background: rgba(139,92,246,.07); border: 1px dashed rgba(167,139,250,.55); box-shadow: none; transform: none; }
.cell.drag-source > *, .cell.drag-source .bar { visibility: hidden; }
.cell.drag-source::before, .cell.drag-source::after { opacity: 0; }
.drag-ghost { position: absolute; z-index: 50; margin: 0; pointer-events: none; content-visibility: visible;
  transform: rotate(1.4deg) scale(1.04); box-shadow: 0 22px 48px rgba(0,0,0,.65); border-color: #a78bfa; }

/* ============ tooltip / boş hal ============ */
.empty-state { display: none; padding: 46px 0; text-align: center; color: var(--txt-3); font-size: 13px; }
.empty-state.show { display: block; }
.name-tip { position: absolute; z-index: 60; max-width: 340px; padding: 10px 13px; border-radius: 10px; background: #070a10; border: 1px solid var(--line-2);
  color: var(--txt); font-size: 12px; font-weight: 600; line-height: 1.45; box-shadow: 0 16px 38px rgba(0,0,0,.65); pointer-events: none;
  white-space: normal; overflow-wrap: anywhere; opacity: 0; visibility: hidden; transform: translateY(4px); transition: opacity .13s ease, transform .13s ease; }
.name-tip.show { opacity: 1; visibility: visible; transform: none; }

@media (prefers-reduced-motion: reduce) {
  .cell, .folder-btn, .icon-btn, .search-input, .h-seg, .cell::after, .name-tip, .delta { transition: none; }
  .cell:hover { transform: none; }
  .folder-page.active { animation: none; }
  .live-dot, .folder-page .cell.status-red::after { animation: none; }
}

/* ---------- folder tab-larının sürüşdürülməsi ---------- */
.folder-tabs { position: relative; }
.tab-grip { display: none; color: #a78bfa; font-size: 11px; margin-right: -2px; }
.dashboard-wrapper.editing .tab-grip { display: inline-block; }
.dashboard-wrapper.editing .folder-tabs { outline: 1px dashed rgba(167,139,250,.25); outline-offset: 6px; border-radius: 14px; }
.dashboard-wrapper.editing .folder-btn { cursor: grab; touch-action: none; }
.dashboard-wrapper.editing .folder-btn:active { cursor: grabbing; }
.folder-btn.tab-source { color: transparent; background: rgba(139,92,246,.07); border-style: dashed; border-color: rgba(167,139,250,.55); box-shadow: none; }
.folder-btn.tab-source * { visibility: hidden; }
.tab-ghost { position: absolute; z-index: 70; margin: 0; pointer-events: none; transform: rotate(-1.2deg) scale(1.05);
  box-shadow: 0 16px 34px rgba(0,0,0,.6); border-color: #a78bfa; }

/* ---------- görünüş keçidi ---------- */
.views { display: flex; gap: 2px; background: var(--surface); border: 1px solid var(--line); border-radius: 10px; padding: 3px; }
.view-btn { background: transparent; border: 0; color: var(--txt-3); font-family: inherit; font-size: 14px; line-height: 1;
  width: 30px; height: 28px; border-radius: 7px; cursor: pointer; transition: background-color .14s, color .14s; }
.view-btn:hover { color: var(--txt-2); }
.view-btn.active { background: var(--surface-2); color: var(--txt); box-shadow: inset 0 0 0 1px var(--line-2); }

/* ---------- hədd zolağı ---------- */
.bar { display: none; position: relative; height: 8px; border-radius: 6px; background: #0b0f17; box-shadow: inset 0 0 0 1px var(--line); overflow: hidden; }
.bar-fill { display: block; height: 100%; width: 0; border-radius: 6px; background: linear-gradient(90deg, color-mix(in srgb, var(--accent) 55%, #000), var(--accent));
  box-shadow: 0 0 10px -2px var(--accent); transition: width .5s cubic-bezier(.4,0,.2,1); }
.bar-mark { position: absolute; top: -1px; bottom: -1px; width: 2px; margin-left: -1px; border-radius: 2px; }
.mark-y { background: rgba(245,158,11,.85); }
.mark-r { background: rgba(244,63,94,.9); }

/* ---------- zolaq (bar) görünüşü ---------- */
#grid.bars .folder-page { grid-template-columns: 1fr; grid-auto-rows: 58px; gap: 8px; }
#grid.bars .cell { flex-direction: row; align-items: center; gap: 14px; padding: 0 16px; border-radius: 12px;
  contain-intrinsic-size: 58px 900px; }
#grid.bars .cell::before, #grid.bars .cell::after { inset: 0 auto 0 0; top: 0; bottom: 0; height: auto; width: 3px; border-radius: 11px 0 0 11px; box-shadow: none; }
#grid.bars .cell::after { width: 3px; background: var(--accent); box-shadow: 0 0 12px -1px var(--accent); }
#grid.bars .cell:hover { transform: translateX(3px); }

#grid.bars .cell-header, #grid.bars .cell-foot, #grid.bars .val-wrap { display: contents; }
#grid.bars .drag-handle { order: 1; }
#grid.bars .name { order: 2; flex: 0 0 28%; min-width: 220px; max-width: 420px; margin: 0; font-size: 14px;
  display: block; white-space: nowrap; text-overflow: ellipsis; }
#grid.bars .bar { order: 3; display: block; flex: 1 1 auto; min-width: 60px; }
#grid.bars .spark { order: 4; flex: 0 0 auto; width: 64px; height: 22px; opacity: .8; }
#grid.bars .val { order: 5; font-size: 21px; letter-spacing: -.4px; text-align: right; min-width: 74px; }
#grid.bars .delta { order: 6; min-width: 54px; }
#grid.bars .badge { order: 7; margin-left: 0; flex: 0 0 auto; min-width: 76px; text-align: center; }
#grid.bars .cell.status-red { background: linear-gradient(90deg, rgba(244,63,94,.10) 0%, #0f141d 42%); }
#grid.bars .cell.over .bar-fill { background: repeating-linear-gradient(115deg, var(--accent) 0 7px, color-mix(in srgb, var(--accent) 55%, #000) 7px 14px); }
#grid.bars .cell.no-thr .bar { background: repeating-linear-gradient(90deg, #141a26 0 5px, transparent 5px 10px); box-shadow: inset 0 0 0 1px var(--line); }

/* ---------- sürüşdürmə anı ---------- */
.dashboard-wrapper.dragging { cursor: grabbing; }
.dashboard-wrapper.dragging * { cursor: grabbing !important; user-select: none; }
.dashboard-wrapper.dragging .cell:hover { transform: none; box-shadow: none; }
.dashboard-wrapper.dragging .folder-btn:hover { background: var(--surface-2); }
.drag-ghost, .tab-ghost { opacity: .96; }

/* ---------- tooltip məzmunu ---------- */
.tip-name { font-size: 13px; font-weight: 700; color: var(--txt); line-height: 1.4; }
.tip-meta { display: inline-flex; align-items: baseline; gap: 6px; margin-top: 7px; padding: 4px 9px; border-radius: 7px;
  background: rgba(139,92,246,.14); box-shadow: inset 0 0 0 1px rgba(167,139,250,.35);
  font-family: var(--mono); font-size: 15px; font-weight: 700; letter-spacing: .6px; color: #c4b5fd; font-variant-numeric: tabular-nums; }

options.onInit:
/* ============================================================
   CronHub — onInit
   • Hər folder ayrıca "səhifə": keçid = 2 class toggle
   • Dəyərlər diff ilə yenilənir, DOM yenidən qurulmur
   • Sparkline tarixçəsi refresh-lərdən yığılır (əlavə sorğu yoxdur)
   ============================================================ */

const S = (htmlNode._state = htmlNode._state || {});

const ORDER_KEY = 'cronhub_dash_order_v2';
const HIST_KEY  = 'cronhub_dash_hist_v1';
const PREF_KEY  = 'cronhub_dash_prefs_v1';
const FOLDER_KEY = 'cronhub_dash_folders_v1';

const SPA_NAV = true;          // false -> tam səhifə yenilənməsi ilə keçid
const SEARCH_DEBOUNCE = 120;
const TIP_DELAY = 140;
const HIST_LEN = 30;           // sparkline üçün nöqtə sayı
const HIST_MIN_GAP = 5000;     // ms — bundan tez-tez nöqtə yazılmır
const HIST_SAVE_GAP = 60000;   // ms — tarixçə localStorage-a bu aralıqla yazılır
const PULSE_LIMIT = 60;        // bundan çox kritik varsa animasiya söndürülür
const SPARK_W = 72, SPARK_H = 26;

S.boxes = []; S.folders = []; S.pages = {}; S.pending = {}; S.tabs = {}; S.cells = {};
S.sig = ''; S.buildToken = 0; S.isDragging = false; S.searchTimer = null;
S.searchQuery = S.searchQuery || '';
S.activeFolder = S.activeFolder || null;
S.hist = S.hist || null;
S.lastPush = S.lastPush || 0;
S.lastSave = S.lastSave || 0;
S.lastData = S.lastData || 0;

function load(key, fallback) {
  try {
    const v = JSON.parse(localStorage.getItem(key) || 'null');
    return (v && typeof v === 'object' && !Array.isArray(v)) ? v : fallback;
  } catch (e) { return fallback; }
}
function save(key, val) { try { localStorage.setItem(key, JSON.stringify(val)); } catch (e) {} }

S.order = load(ORDER_KEY, {});
if (!S.hist) S.hist = load(HIST_KEY, {});
const prefs = load(PREF_KEY, {});
S.folderOrder = (load(FOLDER_KEY, {}).order) || [];
S.sortMode = prefs.sortMode || 'manual';
S.viewMode = prefs.viewMode === 'bars' ? 'bars' : 'grid';
S.statusFilter = prefs.statusFilter || 'all';

function savePrefs() { save(PREF_KEY, { sortMode: S.sortMode, statusFilter: S.statusFilter, viewMode: S.viewMode }); }

/* ---------- köməkçilər ---------- */
const STATUS_RED    = ['status-red', 'CRITICAL', 'red'];
const STATUS_YELLOW = ['status-yellow', 'WARN', 'yellow'];
const STATUS_GREEN  = ['status-green', 'OK', 'green'];

const numCache = new Map();
function fmt(v) {
  const n = Number(v);
  if (!isFinite(n)) return '\u2014';
  const r = Math.round(n);
  let s = numCache.get(r);
  if (s === undefined) {
    s = r.toLocaleString('en-US').replace(/,/g, '\u00a0');
    if (numCache.size > 4000) numCache.clear();
    numCache.set(r, s);
  }
  return s;
}

function statusOf(b) {
  const v = Number(b.value), r = Number(b.red), y = Number(b.yellow);
  if (isFinite(v)) {
    if (Number(b.dir) === 1) {
      /* aşağı düşdükcə pisləşir: dəyər həddən KİÇİK olanda işıqlanır */
      if (isFinite(r) && v <= r) return STATUS_RED;
      if (isFinite(y) && v <= y) return STATUS_YELLOW;
    } else {
      /* yuxarı qalxdıqca pisləşir (default) */
      if (isFinite(r) && v >= r) return STATUS_RED;
      if (isFinite(y) && v >= y) return STATUS_YELLOW;
    }
  }
  return STATUS_GREEN;
}

function fillPct(b) {
  const v = Number(b.value);
  const r = Number(b.red), y = Number(b.yellow);
  const base = (Number(b.dir) === 1)
    ? ((isFinite(y) && y > 0) ? y : ((isFinite(r) && r > 0) ? r * 1.5 : 0))
    : ((isFinite(r) && r > 0) ? r : ((isFinite(y) && y > 0) ? y * 1.5 : 0));
  if (!base || !isFinite(v) || v <= 0) return 0;
  return Math.max(0, Math.min(100, (v / base) * 100));
}

/* Həddlərə görə miqyas: 100% = qırmızı həddin 1.25 misli,
   yəni qırmızı marker həmişə 80%-də, sarı marker öz nisbətində dayanır. */
function barGeom(b) {
  const v = Number(b.value), r = Number(b.red), y = Number(b.yellow);
  const base = (Number(b.dir) === 1)
    ? ((isFinite(y) && y > 0) ? y : ((isFinite(r) && r > 0) ? r * 1.5 : 0))
    : ((isFinite(r) && r > 0) ? r : ((isFinite(y) && y > 0) ? y * 1.5 : 0));
  if (!base) return { fill: 0, y: -1, r: -1, over: false, none: true };
  const scale = base * 1.25;
  const pc = function (n) { return Math.max(0, Math.min(100, (n / scale) * 100)); };
  return {
    fill: isFinite(v) ? pc(v) : 0,
    y: (isFinite(y) && y > 0) ? pc(y) : -1,
    r: (isFinite(r) && r > 0) ? pc(r) : -1,
    over: isFinite(v) && v > scale,
    none: false
  };
}

function sparkPath(arr) {
  if (!arr || arr.length < 2) return null;
  let min = Infinity, max = -Infinity;
  for (let i = 0; i < arr.length; i++) {
    const v = arr[i];
    if (v < min) min = v;
    if (v > max) max = v;
  }
  const span = (max - min) || 1;
  const n = arr.length;
  let line = '';
  for (let i = 0; i < n; i++) {
    const x = (i / (n - 1)) * SPARK_W;
    const y = SPARK_H - 3 - ((arr[i] - min) / span) * (SPARK_H - 7);
    line += (i ? ' ' : '') + x.toFixed(1) + ',' + y.toFixed(1);
  }
  return { line: line, area: '0,' + SPARK_H + ' ' + line + ' ' + SPARK_W + ',' + SPARK_H };
}

/* ---------- kart ---------- */
const SVGNS = 'http://www.w3.org/2000/svg';

function makeCell(b) {
  const st = statusOf(b);

  const cell = document.createElement('div');
  cell.className = 'cell ' + st[0];
  cell.dataset.id = b.id;
  cell.dataset.url = b.url || '';
  cell.dataset.search = String(b.name || '').toLowerCase() + ' ' + String(b.short || '');
  cell.dataset.short = b.short || '';
  cell.dataset.st = st[2];
  cell.dataset.value = isFinite(Number(b.value)) ? String(Number(b.value)) : '';
  cell.setAttribute('aria-label', b.name);
  cell.tabIndex = 0;
  cell.style.setProperty('--fill', fillPct(b).toFixed(1) + '%');

  const header = document.createElement('div');
  header.className = 'cell-header';
  const handle = document.createElement('span');
  handle.className = 'drag-handle';
  handle.draggable = false;
  handle.title = 'Tutub s\u00fcr\u00fc\u015fd\u00fcr';
  handle.textContent = '\u283f';
  const badge = document.createElement('span');
  badge.className = 'badge';
  badge.textContent = st[1];
  header.appendChild(handle);
  header.appendChild(badge);

  const name = document.createElement('div');
  name.className = 'name';
  name.textContent = b.name;

  const foot = document.createElement('div');
  foot.className = 'cell-foot';
  const vw = document.createElement('div');
  vw.className = 'val-wrap';
  const val = document.createElement('span');
  val.className = 'val';
  const txt = fmt(b.value);
  val.textContent = txt;
  const delta = document.createElement('span');
  delta.className = 'delta';
  vw.appendChild(val);
  vw.appendChild(delta);

  const svg = document.createElementNS(SVGNS, 'svg');
  svg.setAttribute('class', 'spark');
  svg.setAttribute('viewBox', '0 0 ' + SPARK_W + ' ' + SPARK_H);
  svg.setAttribute('preserveAspectRatio', 'none');
  svg.setAttribute('aria-hidden', 'true');
  foot.appendChild(vw);
  foot.appendChild(svg);

  cell.appendChild(header);
  cell.appendChild(name);
  cell.appendChild(foot);

  const rec = { root: cell, val: val, badge: badge, delta: delta, svg: svg, area: null, line: null,
                status: st[0], st: st[2], text: txt, fill: -1, spark: '' };
  S.cells[b.id] = rec;
  return cell;
}

function ensureBar(rec) {
  if (rec.bar) return;
  const bar = document.createElement('div');
  bar.className = 'bar';
  const fill = document.createElement('i');
  fill.className = 'bar-fill';
  const my = document.createElement('i');
  my.className = 'bar-mark mark-y';
  const mr = document.createElement('i');
  mr.className = 'bar-mark mark-r';
  bar.appendChild(fill); bar.appendChild(my); bar.appendChild(mr);
  rec.root.insertBefore(bar, rec.root.lastElementChild);
  rec.bar = bar; rec.barFill = fill; rec.markY = my; rec.markR = mr; rec.barSig = '';
}

function paintBar(rec, b) {
  ensureBar(rec);
  const g = barGeom(b);
  const sig = g.fill.toFixed(1) + '|' + g.y.toFixed(1) + '|' + g.r.toFixed(1) + '|' + (g.over ? 1 : 0) + '|' + (g.none ? 1 : 0);
  if (sig === rec.barSig) return;
  rec.barSig = sig;
  rec.barFill.style.width = g.fill.toFixed(1) + '%';
  if (g.y < 0) rec.markY.style.display = 'none';
  else { rec.markY.style.display = ''; rec.markY.style.left = g.y.toFixed(1) + '%'; }
  if (g.r < 0) rec.markR.style.display = 'none';
  else { rec.markR.style.display = ''; rec.markR.style.left = g.r.toFixed(1) + '%'; }
  rec.root.classList.toggle('over', g.over);
  rec.root.classList.toggle('no-thr', g.none);
}

function paintSpark(rec, id) {
  const arr = S.hist[id];
  const sig = arr ? arr.length + ':' + arr[arr.length - 1] : '';
  if (sig === rec.spark) return;
  rec.spark = sig;
  const p = sparkPath(arr);
  if (!p) return;
  if (!rec.line) {
    rec.area = document.createElementNS(SVGNS, 'polygon');
    rec.area.setAttribute('class', 'spark-area');
    rec.line = document.createElementNS(SVGNS, 'polyline');
    rec.line.setAttribute('class', 'spark-line');
    rec.svg.appendChild(rec.area);
    rec.svg.appendChild(rec.line);
  }
  rec.line.setAttribute('points', p.line);
  rec.area.setAttribute('points', p.area);
}

function paintDelta(rec, id) {
  const arr = S.hist[id];
  if (!arr || arr.length < 2) { if (rec.delta.className !== 'delta') rec.delta.className = 'delta'; return; }
  const d = arr[arr.length - 1] - arr[arr.length - 2];
  if (!d) { if (rec.delta.className !== 'delta') { rec.delta.className = 'delta'; rec.delta.textContent = ''; } return; }
  const txt = (d > 0 ? '\u25b2 ' : '\u25bc ') + fmt(Math.abs(d));
  if (rec.delta.textContent !== txt) rec.delta.textContent = txt;
  const cls = 'delta on ' + (d > 0 ? 'up' : 'down');
  if (rec.delta.className !== cls) rec.delta.className = cls;
}

/* ---------- tab-lar və səhifələr ---------- */
S.buildTabs = function () {
  const wrap = htmlNode.querySelector('#folderTabs');
  if (!wrap) return;
  const frag = document.createDocumentFragment();
  S.tabs = {};
  for (let i = 0; i < S.folders.length; i++) {
    const f = S.folders[i];
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'folder-btn';
    btn.dataset.folder = f;
    const grip = document.createElement('span');
    grip.className = 'tab-grip';
    grip.textContent = '\u283f';
    btn.appendChild(grip);
    const label = document.createElement('span');
    label.textContent = f;
    const count = document.createElement('span');
    count.className = 'tab-count zero';
    count.textContent = '0';
    btn.appendChild(label);
    btn.appendChild(count);
    frag.appendChild(btn);
    S.tabs[f] = { btn: btn, count: count, value: -1 };
  }
  wrap.textContent = '';
  wrap.appendChild(frag);
};

S.buildPages = function () {
  const grid = htmlNode.querySelector('#grid');
  if (!grid) return;
  S.pages = {}; S.cells = {}; S.pending = {}; S.buildToken++;

  const byFolder = {};
  for (let i = 0; i < S.boxes.length; i++) {
    const b = S.boxes[i];
    (byFolder[b.folder] || (byFolder[b.folder] = [])).push(b);
  }

  const frag = document.createDocumentFragment();
  for (let i = 0; i < S.folders.length; i++) {
    const f = S.folders[i];
    const page = document.createElement('div');
    page.className = 'folder-page';
    page.dataset.folder = f;

    const ord = S.order[f] || [];
    const pos = {};
    for (let k = 0; k < ord.length; k++) pos[ord[k]] = k;
    const items = byFolder[f] || [];
    items.sort(function (a, b) {
      const ia = pos[a.id] === undefined ? 1e9 : pos[a.id];
      const ib = pos[b.id] === undefined ? 1e9 : pos[b.id];
      return ia - ib;
    });

    S.pending[f] = items;
    S.pages[f] = page;
    frag.appendChild(page);
  }
  grid.textContent = '';
  grid.appendChild(frag);
};

S.ensurePage = function (f) {
  const items = S.pending && S.pending[f];
  if (!items) return;
  delete S.pending[f];
  const page = S.pages[f];
  if (!page) return;
  const pf = document.createDocumentFragment();
  for (let i = 0; i < items.length; i++) {
    pf.appendChild(makeCell(items[i]));
    S.cells[items[i].id].dirty = true;
  }
  page.appendChild(pf);
  if (f === S.activeFolder) S.paintPage(f);
};

/* Qalan folderlər boş vaxtda arxa planda qurulur */
S.prefetch = function (token) {
  if (token !== S.buildToken) return;
  if (!Object.keys(S.pending || {}).length) return;
  const idle = window.requestIdleCallback || function (cb) { return setTimeout(cb, 90); };
  idle(function () {
    if (token !== S.buildToken) return;
    const list = Object.keys(S.pending || {});
    if (!list.length) return;
    S.ensurePage(list[0]);
    S.prefetch(token);
  });
};

/* ---------- yeniləmə (diff) ---------- */
function applyCell(rec, b) {
  const st = statusOf(b);

  const txt = fmt(b.value);
  if (rec.text !== txt) { rec.val.textContent = txt; rec.text = txt; }

  if (rec.status !== st[0]) {
    rec.root.classList.remove(rec.status);
    rec.root.classList.add(st[0]);
    rec.badge.textContent = st[1];
    rec.root.dataset.st = st[2];
    rec.status = st[0]; rec.st = st[2];
  }

  const f = Math.round(fillPct(b) * 10) / 10;
  if (rec.fill !== f) { rec.root.style.setProperty('--fill', f + '%'); rec.fill = f; }

  const nv = Number(b.value);
  const nvs = isFinite(nv) ? String(nv) : '';
  if (rec.root.dataset.value !== nvs) rec.root.dataset.value = nvs;

  const sh = b.short || '';
  if (rec.root.dataset.short !== sh) rec.root.dataset.short = sh;

  paintSpark(rec, b.id);
  paintDelta(rec, b.id);
  if (S.viewMode === 'bars') paintBar(rec, b);
  rec.dirty = false;
}

/* Yalnız görünən səhifənin kartlarına toxunulur; qalanlar "dirty" qalır
   və folder açılanda bir dəfəyə yenilənir. */
S.update = function () {
  const counts = {};
  const live = S.pages[S.activeFolder] || null;

  for (let i = 0; i < S.boxes.length; i++) {
    const b = S.boxes[i];
    const st = statusOf(b);
    const c = counts[b.folder] || (counts[b.folder] = { red: 0, yellow: 0, green: 0, total: 0 });
    c[st[2]]++; c.total++;

    const rec = S.cells[b.id];
    if (!rec) continue;
    if (live && rec.root.parentNode === live) applyCell(rec, b);
    else rec.dirty = true;
  }

  S.counts = counts;

  for (const f in S.tabs) {
    const t = S.tabs[f];
    const n = (counts[f] && counts[f].red) || 0;
    if (t.value !== n) {
      t.value = n;
      t.count.textContent = String(n);
      t.count.classList.toggle('zero', n === 0);
    }
  }
  S.renderStrip();
};

S.renderStrip = function () {
  const c = (S.counts && S.counts[S.activeFolder]) || { red: 0, yellow: 0, green: 0, total: 0 };
  const chips = htmlNode.querySelector('#chips');
  if (chips) {
    const map = { all: c.total, red: c.red, yellow: c.yellow, green: c.green };
    const btns = chips.children;
    for (let i = 0; i < btns.length; i++) {
      const b = btns[i];
      const k = b.dataset.status;
      const n = map[k] || 0;
      const nEl = b.firstElementChild;
      if (nEl.textContent !== String(n)) nEl.textContent = String(n);
      b.classList.toggle('empty', k !== 'all' && n === 0);
      b.classList.toggle('active', S.statusFilter === k);
    }
  }
  const health = htmlNode.querySelector('#health');
  if (health) {
    const t = c.total || 1;
    const segs = health.children;
    segs[0].style.width = (c.green / t * 100) + '%';
    segs[1].style.width = (c.yellow / t * 100) + '%';
    segs[2].style.width = (c.red / t * 100) + '%';
  }
  const page = S.pages[S.activeFolder];
  if (page) page.classList.toggle('no-pulse', c.red > PULSE_LIMIT);
};

S.paintPage = function (f) {
  const page = S.pages[f];
  if (!page || !S.byId) return;
  const kids = page.children;
  for (let i = 0; i < kids.length; i++) {
    const id = kids[i].dataset.id;
    const rec = S.cells[id];
    const b = S.byId[id];
    if (!rec || !b || !rec.dirty) continue;
    applyCell(rec, b);
  }
};

S.markTab = function () {
  for (const f in S.tabs) S.tabs[f].btn.classList.toggle('active', f === S.activeFolder);
};

/* ---------- filtr + sıralama ---------- */
S.applyFilters = function () {
  const page = S.pages[S.activeFolder];
  const empty = htmlNode.querySelector('#emptyState');
  if (!page) { if (empty) empty.classList.remove('show'); return; }

  const q = (S.searchQuery || '').trim().toLowerCase();
  const sf = S.statusFilter;
  const kids = page.children;
  let visible = 0;

  for (let i = 0; i < kids.length; i++) {
    const c = kids[i];
    const hide = (q && c.dataset.search.indexOf(q) === -1) || (sf !== 'all' && c.dataset.st !== sf);
    if (c.classList.contains('hidden') !== hide) c.classList.toggle('hidden', hide);
    if (!hide) visible++;
  }
  if (empty) empty.classList.toggle('show', visible === 0);
};

S.applySort = function () {
  const page = S.pages[S.activeFolder];
  if (!page || !page.children.length) return;
  const kids = Array.prototype.slice.call(page.children);
  const mode = S.sortMode;
  let arr;

  if (mode === 'manual') {
    const ord = S.order[S.activeFolder];
    if (!ord || !ord.length) return;
    const pos = {};
    for (let i = 0; i < ord.length; i++) pos[ord[i]] = i;
    arr = kids.slice().sort(function (a, b) {
      const ia = pos[a.dataset.id] === undefined ? 1e9 : pos[a.dataset.id];
      const ib = pos[b.dataset.id] === undefined ? 1e9 : pos[b.dataset.id];
      return ia - ib;
    });
  } else if (mode === 'name') {
    arr = kids.slice().sort(function (a, b) { return a.dataset.search.localeCompare(b.dataset.search, 'az'); });
  } else if (mode === 'value') {
    arr = kids.slice().sort(function (a, b) {
      const va = a.dataset.value === '' ? -Infinity : Number(a.dataset.value);
      const vb = b.dataset.value === '' ? -Infinity : Number(b.dataset.value);
      return vb - va;
    });
  } else {
    const rank = { red: 0, yellow: 1, green: 2 };
    arr = kids.slice().sort(function (a, b) {
      const ra = rank[a.dataset.st], rb = rank[b.dataset.st];
      if (ra !== rb) return ra - rb;
      const va = a.dataset.value === '' ? -Infinity : Number(a.dataset.value);
      const vb = b.dataset.value === '' ? -Infinity : Number(b.dataset.value);
      return vb - va;
    });
  }

  let same = true;
  for (let i = 0; i < arr.length; i++) if (arr[i] !== kids[i]) { same = false; break; }
  if (same) return;

  const frag = document.createDocumentFragment();
  for (let i = 0; i < arr.length; i++) frag.appendChild(arr[i]);
  page.appendChild(frag);
};

S.markSort = function () {
  const box = htmlNode.querySelector('#sorts');
  if (!box) return;
  const b = box.children;
  for (let i = 0; i < b.length; i++) b[i].classList.toggle('active', b[i].dataset.sort === S.sortMode);
};

S.setSort = function (mode) {
  if (!mode || mode === S.sortMode) return;
  S.sortMode = mode;
  S.markSort();
  savePrefs();
  S.applySort();
  S.applyFilters();
};

S.markView = function () {
  const box = htmlNode.querySelector('#views');
  if (box) {
    const b = box.children;
    for (let i = 0; i < b.length; i++) b[i].classList.toggle('active', b[i].dataset.view === S.viewMode);
  }
  const grid = htmlNode.querySelector('#grid');
  if (grid) grid.classList.toggle('bars', S.viewMode === 'bars');
};

S.setView = function (m) {
  if (!m || m === S.viewMode) return;
  S.viewMode = m;
  S.markView();
  savePrefs();
  S.hideTip();
  for (const k in S.cells) S.cells[k].dirty = true;
  S.paintPage(S.activeFolder);
};

S.setStatusFilter = function (st) {
  S.statusFilter = (S.statusFilter === st && st !== 'all') ? 'all' : st;
  savePrefs();
  S.renderStrip();
  S.applyFilters();
};

S.setFolder = function (f) {
  if (!f || f === S.activeFolder || !S.pages[f]) return;
  if (S.hideTip) S.hideTip();
  S.ensurePage(f);
  const prev = S.pages[S.activeFolder];
  if (prev) prev.classList.remove('active');
  S.activeFolder = f;
  S.pages[f].classList.add('active');
  S.paintPage(f);
  S.markTab();
  S.applySort();
  S.applyFilters();
  S.renderStrip();
  const grid = htmlNode.querySelector('#grid');
  if (grid) grid.scrollTop = 0;
};

/* ---------- naviqasiya ---------- */
S.go = function (url, newTab) {
  if (!url) return;
  if (newTab) { window.open(url, '_blank', 'noopener'); return; }
  if (SPA_NAV && url.charAt(0) === '/' && window.history && window.history.pushState) {
    try {
      window.history.pushState({}, '', url);
      window.dispatchEvent(new PopStateEvent('popstate', { state: {} }));
      return;
    } catch (e) {}
  }
  window.location.assign(url);
};

/* ---------- tarixçə ---------- */
function pushHistory(list) {
  const now = Date.now();
  if (now - S.lastPush < HIST_MIN_GAP) return false;
  S.lastPush = now;
  const seen = {};
  for (let i = 0; i < list.length; i++) {
    const b = list[i];
    const v = Number(b.value);
    if (!isFinite(v)) continue;
    seen[b.id] = 1;
    const a = S.hist[b.id] || (S.hist[b.id] = []);
    a.push(v);
    if (a.length > HIST_LEN) a.splice(0, a.length - HIST_LEN);
  }
  for (const k in S.hist) if (!seen[k]) delete S.hist[k];
  if (list.length <= 800 && now - (S.lastSave || 0) > HIST_SAVE_GAP) {
    S.lastSave = now;
    const idle = window.requestIdleCallback || function (cb) { return setTimeout(cb, 200); };
    idle(function () { save(HIST_KEY, S.hist); });
  }
  return true;
}

/* ---------- onRender bunu çağırır ---------- */
function orderFolders(folders) {
  const ord = S.folderOrder || [];
  const pos = {};
  for (let i = 0; i < ord.length; i++) pos[ord[i]] = i;
  return folders.slice().sort(function (a, b) {
    const ia = pos[a] === undefined ? 1e9 : pos[a];
    const ib = pos[b] === undefined ? 1e9 : pos[b];
    if (ia !== ib) return ia - ib;
    return a.localeCompare(b, 'az');
  });
}

function makeSig(list, folders) {
  let sig = folders.join('\u0001') + '\u0002';
  for (let i = 0; i < list.length; i++) sig += list[i].id + '\u0003' + list[i].folder + '\u0003' + list[i].name + '\u0001';
  return sig;
}

S.saveFolderOrder = function () {
  const wrap = htmlNode.querySelector('#folderTabs');
  if (!wrap) return;
  const arr = [];
  const ch = wrap.children;
  for (let i = 0; i < ch.length; i++) {
    if (!ch[i].classList.contains('tab-ghost')) arr.push(ch[i].dataset.folder);
  }
  S.folderOrder = arr;
  S.folders = arr.slice();
  save(FOLDER_KEY, { order: arr });

  const grid = htmlNode.querySelector('#grid');
  if (grid) for (let i = 0; i < arr.length; i++) { const pg = S.pages[arr[i]]; if (pg) grid.appendChild(pg); }
  S.sig = makeSig(S.boxes, S.folders);
};

S.sync = function (list, folders) {
  S.boxes = list;
  S.folders = orderFolders(folders);
  folders = S.folders;
  const byId = {};
  for (let i = 0; i < list.length; i++) byId[list[i].id] = list[i];
  S.byId = byId;
  S.lastData = Date.now();
  pushHistory(list);

  const sig = makeSig(list, folders);

  if (sig !== S.sig) {
    S.sig = sig;
    S.buildTabs();
    S.buildPages();
    if (!S.activeFolder || folders.indexOf(S.activeFolder) === -1) S.activeFolder = folders[0] || null;
    S.ensurePage(S.activeFolder);
    const p = S.pages[S.activeFolder];
    if (p) p.classList.add('active');
    S.markTab();
    S.markSort();
    S.prefetch(S.buildToken);
  }

  if (!S.isDragging) S.sweepDrag();
  S.update();
  S.applySort();
  S.applyFilters();
  S.tick();
};

S.tick = function () {
  const el = htmlNode.querySelector('#liveText');
  const live = htmlNode.querySelector('.live');
  if (!el || !S.lastData) return;
  const s = Math.max(0, Math.round((Date.now() - S.lastData) / 1000));
  const txt = s < 5 ? 'indi' : (s < 60 ? s + ' san' : Math.round(s / 60) + ' d\u0259q');
  if (el.textContent !== txt) el.textContent = txt;
  if (live) live.classList.toggle('stale', s > 120);
};

S.saveOrder = function () {
  const page = S.pages[S.activeFolder];
  if (!page) return;
  const ids = [];
  const ch = page.children;
  for (let i = 0; i < ch.length; i++) if (!ch[i].classList.contains('drag-ghost')) ids.push(ch[i].dataset.id);
  S.order[S.activeFolder] = ids;
  save(ORDER_KEY, S.order);
};

/* ---------- düzəliş rejimi ---------- */
S.setEditMode = function (on) {
  S.editMode = !!on;
  const wrap = htmlNode.querySelector('.dashboard-wrapper');
  if (wrap) wrap.classList.toggle('editing', S.editMode);
  const btn = htmlNode.querySelector('#editToggle');
  if (btn) {
    btn.classList.toggle('active', S.editMode);
    btn.setAttribute('aria-pressed', String(S.editMode));
  }
  if (!S.editMode) { S.endDrag(); if (S.endTabDrag) S.endTabDrag(); }
};

/* ---------- tooltip ---------- */
S.hideTip = function () {
  clearTimeout(S.tipTimer);
  const tip = htmlNode.querySelector('#nameTip');
  if (tip) tip.classList.remove('show');
};

S.showTip = function (cell) {
  const tip = htmlNode.querySelector('#nameTip');
  const wrap = htmlNode.querySelector('.dashboard-wrapper');
  if (!tip || !wrap || !cell || !cell.isConnected) return;
  const nameEl = cell.querySelector('.name');
  if (!nameEl) return;

  if (!tip.firstElementChild) {
    const t = document.createElement('div'); t.className = 'tip-name';
    const m = document.createElement('div'); m.className = 'tip-meta';
    tip.textContent = '';
    tip.appendChild(t); tip.appendChild(m);
  }
  const tName = tip.firstElementChild;
  const tMeta = tip.lastElementChild;

  if (tName.textContent !== nameEl.textContent) tName.textContent = nameEl.textContent;
  const sh = cell.dataset.short || '';
  const meta = sh ? 'ID \u00b7 ' + sh : '';
  if (tMeta.textContent !== meta) tMeta.textContent = meta;
  tMeta.style.display = meta ? '' : 'none';

  tip.classList.add('show');

  const c = cell.getBoundingClientRect();
  const wr = wrap.getBoundingClientRect();
  let left = c.left - wr.left + (c.width - tip.offsetWidth) / 2;
  left = Math.max(6, Math.min(left, wr.width - tip.offsetWidth - 6));
  let top = c.top - wr.top - tip.offsetHeight - 8;
  if (top < 4) top = c.bottom - wr.top + 8;
  tip.style.left = Math.round(left) + 'px';
  tip.style.top = Math.round(top) + 'px';
};

/* ---------- sürüşdürmə (pointer: mouse + toxunma) ---------- */
const D = (S.drag = S.drag || {});
function gridEl() { return htmlNode.querySelector('#grid'); }

function cacheRects() {
  const page = S.pages[S.activeFolder];
  D.items = [];
  if (!page) return;
  const kids = page.children;
  for (let i = 0; i < kids.length; i++) {
    const c = kids[i];
    if (c === D.el || c === D.ghost || c.classList.contains('hidden')) continue;
    D.items.push({ el: c, r: c.getBoundingClientRect() });
  }
}

function moveGhost() {
  const grid = gridEl();
  if (!grid || !D.ghost) return;
  const g = grid.getBoundingClientRect();
  D.ghost.style.left = (D.x - g.left + grid.scrollLeft - D.offX) + 'px';
  D.ghost.style.top = (D.y - g.top + grid.scrollTop - D.offY) + 'px';
}

function reorder() {
  if (!D.el || !D.el.parentNode || !D.items) return;
  let best = null, bestD = Infinity;
  for (let i = 0; i < D.items.length; i++) {
    const r = D.items[i].r;
    const dx = D.x - (r.left + r.width / 2), dy = D.y - (r.top + r.height / 2);
    const d = dx * dx + dy * dy;
    if (d < bestD) { bestD = d; best = D.items[i].el; }
  }
  if (!best || best === D.el || best.parentNode !== D.el.parentNode) return;
  const kids = Array.prototype.slice.call(D.el.parentNode.children);
  if (kids.indexOf(D.el) < kids.indexOf(best)) {
    if (best.nextElementSibling === D.el) return;
    best.after(D.el);
  } else {
    if (best.previousElementSibling === D.el) return;
    best.before(D.el);
  }
  cacheRects();
}

function loop() {
  if (!D.active) { D.raf = 0; return; }
  const grid = gridEl();
  if (grid) {
    const g = grid.getBoundingClientRect();
    const edge = 64;
    let dy = 0;
    if (D.y < g.top + edge) dy = -Math.min(26, (g.top + edge - D.y) / 2);
    else if (D.y > g.bottom - edge) dy = Math.min(26, (D.y - (g.bottom - edge)) / 2);
    if (dy) { grid.scrollTop += dy; cacheRects(); }
  }
  moveGhost();
  reorder();
  D.raf = requestAnimationFrame(loop);
}

function beginDrag() {
  const cell = D.el, grid = gridEl();
  if (!cell || !grid) return;
  if (S.sortMode !== 'manual') S.setSort('manual');
  const r = cell.getBoundingClientRect();
  D.offX = D.startX - r.left;
  D.offY = D.startY - r.top;

  const ghost = cell.cloneNode(true);
  ghost.classList.add('drag-ghost');
  ghost.classList.remove('hidden', 'drag-source');
  ghost.removeAttribute('tabindex');
  ghost.style.width = r.width + 'px';
  ghost.style.height = r.height + 'px';
  grid.appendChild(ghost);

  D.ghost = ghost;
  D.active = true;
  S.isDragging = true;
  S.hideTip();
  const wrp = htmlNode.querySelector('.dashboard-wrapper');
  if (wrp) wrp.classList.add('dragging');
  cell.classList.add('drag-source');
  cacheRects();
  moveGhost();
  if (!D.raf) D.raf = requestAnimationFrame(loop);
}

/* Nə vaxtsa yarımçıq qalmış sürüşmə izlərini silir (solğun qalan kart/tab). */
S.sweepDrag = function () {
  const stale = htmlNode.querySelectorAll('.drag-source, .tab-source, .drag-ghost, .tab-ghost');
  for (let i = 0; i < stale.length; i++) {
    const el = stale[i];
    if (el.classList.contains('drag-ghost') || el.classList.contains('tab-ghost')) {
      if (el.parentNode) el.parentNode.removeChild(el);
    } else {
      el.classList.remove('drag-source', 'tab-source');
    }
  }
  const wrp = htmlNode.querySelector('.dashboard-wrapper');
  if (wrp) wrp.classList.remove('dragging');
};

S.endDrag = function () {
  const was = D.active;
  const wrp = htmlNode.querySelector('.dashboard-wrapper');
  if (wrp) wrp.classList.remove('dragging');
  if (D.raf) { cancelAnimationFrame(D.raf); D.raf = 0; }
  if (D.ghost && D.ghost.parentNode) D.ghost.parentNode.removeChild(D.ghost);
  if (D.el) D.el.classList.remove('drag-source');
  D.ghost = null; D.el = null; D.items = null;
  D.active = false; D.pending = false; D.pointerId = null;
  if (was) { S.saveOrder(); setTimeout(function () { S.isDragging = false; }, 60); }
  else S.isDragging = false;
};


/* ---------- folder tab-larının sürüşdürülməsi ---------- */
const T = (S.tabDrag = S.tabDrag || {});

function tabsEl() { return htmlNode.querySelector('#folderTabs'); }

function tabCache() {
  const wrap = tabsEl();
  T.items = [];
  if (!wrap) return;
  const ch = wrap.children;
  for (let i = 0; i < ch.length; i++) {
    const b = ch[i];
    if (b === T.el || b.classList.contains('tab-ghost')) continue;
    T.items.push({ el: b, r: b.getBoundingClientRect() });
  }
}

function tabMoveGhost() {
  const wrap = tabsEl();
  if (!wrap || !T.ghost) return;
  const w = wrap.getBoundingClientRect();
  T.ghost.style.left = (T.x - w.left - T.offX) + 'px';
  T.ghost.style.top = (T.y - w.top - T.offY) + 'px';
}

function tabReorder() {
  if (!T.el || !T.items) return;
  let best = null, bestD = Infinity;
  for (let i = 0; i < T.items.length; i++) {
    const r = T.items[i].r;
    const dx = T.x - (r.left + r.width / 2);
    const dy = T.y - (r.top + r.height / 2);
    const d = dx * dx + dy * dy * 4;
    if (d < bestD) { bestD = d; best = T.items[i].el; }
  }
  if (!best || best === T.el) return;
  const kids = Array.prototype.slice.call(T.el.parentNode.children);
  if (kids.indexOf(T.el) < kids.indexOf(best)) {
    if (best.nextElementSibling === T.el) return;
    best.after(T.el);
  } else {
    if (best.previousElementSibling === T.el) return;
    best.before(T.el);
  }
  tabCache();
}

function tabLoop() {
  if (!T.active) { T.raf = 0; return; }
  tabMoveGhost();
  tabReorder();
  T.raf = requestAnimationFrame(tabLoop);
}

function tabBegin() {
  const btn = T.el, wrap = tabsEl();
  if (!btn || !wrap) return;
  const r = btn.getBoundingClientRect();
  T.offX = T.startX - r.left;
  T.offY = T.startY - r.top;
  const ghost = btn.cloneNode(true);
  ghost.classList.add('tab-ghost');
  ghost.style.width = r.width + 'px';
  ghost.style.height = r.height + 'px';
  wrap.appendChild(ghost);
  T.ghost = ghost;
  T.active = true;
  S.isDragging = true;
  const wrp2 = htmlNode.querySelector('.dashboard-wrapper');
  if (wrp2) wrp2.classList.add('dragging');
  btn.classList.add('tab-source');
  tabCache();
  tabMoveGhost();
  if (!T.raf) T.raf = requestAnimationFrame(tabLoop);
}

S.endTabDrag = function () {
  const was = T.active;
  const wrp = htmlNode.querySelector('.dashboard-wrapper');
  if (wrp) wrp.classList.remove('dragging');
  if (T.raf) { cancelAnimationFrame(T.raf); T.raf = 0; }
  if (T.ghost && T.ghost.parentNode) T.ghost.parentNode.removeChild(T.ghost);
  if (T.el) T.el.classList.remove('tab-source');
  T.ghost = null; T.el = null; T.items = null;
  T.active = false; T.pending = false; T.pointerId = null;
  if (was) { S.saveFolderOrder(); setTimeout(function () { S.isDragging = false; }, 60); }
};

/* ---------- hadisələr ---------- */
if (!htmlNode._eventsInitialized) {
  htmlNode._eventsInitialized = true;

  htmlNode.addEventListener('click', function (e) {
    const tab = e.target.closest('.folder-btn');
    if (tab) {
      e.preventDefault(); e.stopPropagation();
      if (!S.isDragging) S.setFolder(tab.dataset.folder);
      return;
    }

    const chip = e.target.closest('.chip');
    if (chip) { e.preventDefault(); e.stopPropagation(); S.setStatusFilter(chip.dataset.status); return; }

    const viewBtn = e.target.closest('.view-btn');
    if (viewBtn) { e.preventDefault(); e.stopPropagation(); S.setView(viewBtn.dataset.view); return; }

    const sortBtn = e.target.closest('.sort-btn');
    if (sortBtn) { e.preventDefault(); e.stopPropagation(); S.setSort(sortBtn.dataset.sort); return; }

    if (e.target.closest('#editToggle')) { e.preventDefault(); e.stopPropagation(); S.setEditMode(!S.editMode); return; }

    if (e.target.closest('#resetOrder')) {
      e.preventDefault(); e.stopPropagation();
      S.order = {};
      S.folderOrder = [];
      try { localStorage.removeItem(ORDER_KEY); localStorage.removeItem(FOLDER_KEY); } catch (err) {}
      S.sig = '';
      S.sync(S.boxes, S.folders);
      return;
    }

    const cell = e.target.closest('.cell');
    if (cell && !S.isDragging && !S.editMode && !e.target.closest('.drag-handle')) {
      e.stopPropagation();
      S.go(cell.dataset.url, e.ctrlKey || e.metaKey || e.button === 1);
    }
  });

  const tabsWrap = htmlNode.querySelector('#folderTabs');
  if (tabsWrap) {
    tabsWrap.addEventListener('pointerdown', function (e) {
      if (!S.editMode) return;
      if (e.pointerType === 'mouse' && e.button !== 0) return;
      const btn = e.target.closest('.folder-btn');
      if (!btn) return;
      e.preventDefault();
      T.el = btn; T.handle = tabsWrap; T.pending = true; T.pointerId = e.pointerId;
      T.startX = T.x = e.clientX; T.startY = T.y = e.clientY;
      try { tabsWrap.setPointerCapture(e.pointerId); } catch (err) {}
    });

    tabsWrap.addEventListener('pointermove', function (e) {
      if (T.pointerId !== e.pointerId) return;
      if (!T.pending && !T.active) return;
      T.x = e.clientX; T.y = e.clientY;
      if (!T.active) {
        const dx = T.x - T.startX, dy = T.y - T.startY;
        if (dx * dx + dy * dy < 16) return;
        T.pending = false;
        tabBegin();
      }
      e.preventDefault();
    });

    const tabFinish = function (e) {
      if (T.pointerId !== e.pointerId) return;
      try { if (T.handle) T.handle.releasePointerCapture(e.pointerId); } catch (err) {}
      S.endTabDrag();
    };
    tabsWrap.addEventListener('pointerup', tabFinish);
    tabsWrap.addEventListener('pointercancel', tabFinish);
    tabsWrap.addEventListener('lostpointercapture', function (e) {
      if (T.pointerId === e.pointerId && (T.active || T.pending)) S.endTabDrag();
    });
    tabsWrap.addEventListener('dragstart', function (e) { e.preventDefault(); });
  }

  const search = htmlNode.querySelector('#searchBox');
  if (search) {
    search.addEventListener('input', function (e) {
      const v = e.target.value;
      clearTimeout(S.searchTimer);
      S.searchTimer = setTimeout(function () { S.searchQuery = v; S.applyFilters(); }, SEARCH_DEBOUNCE);
    });
  }

  const grid = htmlNode.querySelector('#grid');
  if (grid) {
    grid.addEventListener('pointerdown', function (e) {
      if (!S.editMode) return;
      if (e.pointerType === 'mouse' && e.button !== 0) return;
      const handle = e.target.closest('.drag-handle');
      if (!handle) return;
      const cell = handle.closest('.cell');
      if (!cell) return;
      e.preventDefault();
      D.el = cell; D.handle = grid; D.pending = true; D.pointerId = e.pointerId;
      D.startX = D.x = e.clientX; D.startY = D.y = e.clientY;
      /* Capture kartın özünə deyil, #grid-ə verilir: kart sürüşmə zamanı
         DOM-da yerini dəyişir, capture isə köçürülən elementdən itir. */
      try { grid.setPointerCapture(e.pointerId); } catch (err) {}
    });

    grid.addEventListener('pointermove', function (e) {
      if (D.pointerId !== e.pointerId) return;
      if (!D.pending && !D.active) return;
      D.x = e.clientX; D.y = e.clientY;
      if (!D.active) {
        const dx = D.x - D.startX, dy = D.y - D.startY;
        if (dx * dx + dy * dy < 20) return;
        D.pending = false;
        beginDrag();
      }
      e.preventDefault();
    });

    const finish = function (e) {
      if (D.pointerId !== e.pointerId) return;
      try { if (D.handle) D.handle.releasePointerCapture(e.pointerId); } catch (err) {}
      S.endDrag();
    };
    grid.addEventListener('pointerup', finish);
    grid.addEventListener('pointercancel', finish);
    grid.addEventListener('lostpointercapture', function (e) {
      if (D.pointerId === e.pointerId && (D.active || D.pending)) S.endDrag();
    });
    grid.addEventListener('dragstart', function (e) { e.preventDefault(); });

    grid.addEventListener('mouseover', function (e) {
      if (S.isDragging) return;
      const cell = e.target.closest('.cell');
      if (!cell || cell === S.tipHover || cell.classList.contains('drag-ghost')) return;
      S.tipHover = cell;
      S.hideTip();
      S.tipTimer = setTimeout(function () {
        if (S.tipHover === cell && !S.isDragging) S.showTip(cell);
      }, TIP_DELAY);
    });
    grid.addEventListener('mouseout', function (e) {
      const cell = e.target.closest('.cell');
      if (!cell) return;
      if (e.relatedTarget && cell.contains(e.relatedTarget)) return;
      S.tipHover = null;
      S.hideTip();
    });
    grid.addEventListener('scroll', function () { S.tipHover = null; S.hideTip(); }, { passive: true });
  }

  /* kart üzərində klaviatura */
  htmlNode.addEventListener('keydown', function (e) {
    const tabBtn = e.target && e.target.closest ? e.target.closest('.folder-btn') : null;
    if (tabBtn && S.editMode && (e.ctrlKey || e.metaKey)) {
      let step = 0;
      if (e.key === 'ArrowRight') step = 1;
      else if (e.key === 'ArrowLeft') step = -1;
      else return;
      e.preventDefault();
      const kids = Array.prototype.slice.call(tabBtn.parentNode.children);
      const i = kids.indexOf(tabBtn);
      const j = Math.max(0, Math.min(kids.length - 1, i + step));
      if (j === i) return;
      if (j > i) kids[j].after(tabBtn); else kids[j].before(tabBtn);
      tabBtn.focus();
      S.saveFolderOrder();
      return;
    }

    const cell = e.target && e.target.closest ? e.target.closest('.cell') : null;
    if (!cell) return;
    if (!S.editMode) {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); S.go(cell.dataset.url, false); }
      return;
    }
    if (!e.ctrlKey && !e.metaKey) return;
    const page = cell.parentNode;
    const kids = Array.prototype.slice.call(page.children).filter(function (c) {
      return !c.classList.contains('hidden') && !c.classList.contains('drag-ghost');
    });
    const i = kids.indexOf(cell);
    if (i === -1) return;
    let step = 0;
    if (e.key === 'ArrowRight') step = 1;
    else if (e.key === 'ArrowLeft') step = -1;
    else if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
      const cols = Math.max(1, Math.round(page.clientWidth / (cell.offsetWidth + 12)));
      step = e.key === 'ArrowDown' ? cols : -cols;
    } else return;
    e.preventDefault();
    const j = Math.max(0, Math.min(kids.length - 1, i + step));
    if (j === i) return;
    if (S.sortMode !== 'manual') S.setSort('manual');
    if (j > i) kids[j].after(cell); else kids[j].before(cell);
    cell.focus();
    S.saveOrder();
  });

  /* qısayollar — yalnız kursor panelin üstündə olanda */
  const wrapEl = htmlNode.querySelector('.dashboard-wrapper');
  if (wrapEl) {
    wrapEl.addEventListener('mouseenter', function () { S.hover = true; });
    wrapEl.addEventListener('mouseleave', function () { S.hover = false; });
  }

  S.onKey = function (e) {
    const inSearch = e.target && e.target.id === 'searchBox';
    if (inSearch) {
      if (e.key === 'Escape') { e.target.value = ''; S.searchQuery = ''; S.applyFilters(); e.target.blur(); }
      return;
    }
    if (!S.hover && !(e.target && e.target.closest && e.target.closest('.dashboard-wrapper'))) return;
    if (e.ctrlKey || e.metaKey || e.altKey) return;

    if (e.key === '/') {
      const inp = htmlNode.querySelector('#searchBox');
      if (inp) { e.preventDefault(); e.stopPropagation(); inp.focus(); inp.select(); }
      return;
    }
    if (e.key === 'e' || e.key === 'E') { e.stopPropagation(); S.setEditMode(!S.editMode); return; }
    if (e.key === 'v' || e.key === 'V') { e.stopPropagation(); S.setView(S.viewMode === 'bars' ? 'grid' : 'bars'); return; }
    if (e.key === 'Escape') { if (S.editMode) { e.stopPropagation(); S.setEditMode(false); } return; }
    if (e.key >= '1' && e.key <= '9') {
      const f = S.folders[Number(e.key) - 1];
      if (f) { e.stopPropagation(); S.setFolder(f); }
    }
  };
  document.addEventListener('keydown', S.onKey, true);

  /* Ehtiyat tor: kursor panelin xaricində buraxılsa və ya pəncərə fokusu itsə */
  S.onGlobalUp = function () {
    if (S.drag && (S.drag.active || S.drag.pending)) S.endDrag();
    if (S.tabDrag && (S.tabDrag.active || S.tabDrag.pending)) S.endTabDrag();
  };
  window.addEventListener('pointerup', S.onGlobalUp, true);
  window.addEventListener('pointercancel', S.onGlobalUp, true);
  window.addEventListener('blur', S.onGlobalUp);

  S.timer = setInterval(function () { S.tick(); }, 5000);

  htmlNode.onpanelwillunmount = function () {
    document.removeEventListener('keydown', S.onKey, true);
    window.removeEventListener('pointerup', S.onGlobalUp, true);
    window.removeEventListener('pointercancel', S.onGlobalUp, true);
    window.removeEventListener('blur', S.onGlobalUp);
    clearInterval(S.timer);
    if (D.raf) cancelAnimationFrame(D.raf);
  };
}

S.markSort();
S.markView();

options.onRender:
/* CronHub — onRender
   Yalnız data oxuyur və S.sync()-ə ötürür. DOM burada qurulmur. */

const S = htmlNode._state;
if (!S || !S.sync) return;

function lastValue(values) {
  if (!values) return NaN;
  if (typeof values.length === 'number') {
    const n = values.length;
    if (!n) return NaN;
    return Number(typeof values.get === 'function' ? values.get(n - 1) : values[n - 1]);
  }
  if (typeof values.toArray === 'function') {
    const a = values.toArray();
    return a.length ? Number(a[a.length - 1]) : NaN;
  }
  return NaN;
}

const boxes = Object.create(null);
const folderSet = Object.create(null);
const series = data.series || [];

for (let s = 0; s < series.length; s++) {
  const frame = series[s];
  const fields = frame.fields;
  if (!fields || !fields.length) continue;

  let vf = null;
  for (let i = 0; i < fields.length; i++) {
    if (fields[i].type === 'number') { vf = fields[i]; break; }
  }
  if (!vf) vf = fields[1] || fields[0];
  if (!vf) continue;

  const labels = vf.labels || (fields[1] && fields[1].labels) || (fields[0] && fields[0].labels) || {};
  const jid = labels.job_id || labels.instance || frame.name;
  if (!jid) continue;

  const val = lastValue(vf.values);
  const folder = labels.folder || 'Di\u011f\u0259r';
  folderSet[folder] = true;

  let b = boxes[jid];
  if (!b) {
    b = boxes[jid] = {
      id: jid,
      name: labels.panelname || labels.job_name || jid,
      folder: folder,
      url: labels.link || labels.url || ('/d/' + encodeURIComponent(jid)),
      short: labels.short_id || '',
      value: NaN, red: NaN, yellow: NaN, dir: 0
    };
  }
  if (!b.short && labels.short_id) b.short = labels.short_id;

  const refId = String(frame.refId || (frame.meta && frame.meta.refId) || '').toUpperCase();
  if (refId === 'A') b.value = val;
  else if (refId === 'B') b.red = val;
  else if (refId === 'C') b.yellow = val;
  else if (refId === 'D') b.dir = val;
}

const list = [];
for (const k in boxes) list.push(boxes[k]);

const folders = Object.keys(folderSet).sort(function (a, b) {
  return a.localeCompare(b, 'az');
});

S.sync(list, folders);
